    const handleItemClick = useCallback((item) => {
        // Если в description есть ссылка, открываем её
        if (item.description && item.description.trim()) {
            const url = item.description.trim();
            // Проверяем, начинается ли с http:// или https://
            if (url.startsWith('http://') || url.startsWith('https://')) {
                window.open(url, '_blank');
            } else {
                // Если нет протокола, добавляем https://
                window.open('https://' + url, '_blank');
            }
        }
    }, []);

    const cancelDeleteItem = useCallback(() => {
        setShowDeleteConfirm(false);
        setItemToDelete(null);
    }, []);

    return (
        <div className="dashboard">
            <div className="navigation-menus-section">
                <div className="navigation-menus-grid">
                    {navigationMenus.map((menu) => (
                        <div
                            key={menu.id}
                            className="navigation-menu-card"
                            onMouseEnter={(e) => handleMenuEnter(menu.id, e)}
                            onMouseLeave={handleCardLeave}
                        >
                            <div className="menu-card-header">
                                <span className="menu-card-title">{menu.title}</span>
                            </div>
                        </div>
                    ))}
                </div>

                {hoveredMenu && currentMenu && (
                    <div
                        className="menu-dropdown-positioned"
                        style={{ top: menuPosition.top, left: menuPosition.left }}
                        onMouseEnter={handleDropdownEnter}
                        onMouseLeave={handleDropdownLeave}
                    >
                        {isAdmin && (
                            <div className="dropdown-add-section">
                                <button
                                    className="dropdown-add-btn"
                                    onClick={() => handleAddContent(hoveredMenu)}
                                >
                                    Добавить
                                </button>
                            </div>
                        )}
                        {currentMenu.items.length > 0 ? (
                            currentMenu.items.map((item) => (
                                <div
                                    key={item.id}
                                    className="menu-dropdown-item"
                                    onMouseEnter={(e) => {
                                        if (item.hasSubmenu) {
                                            handleSubmenuEnter('broadcasts-guests', e);
                                        }
                                    }}
                                    onClick={() => !item.hasSubmenu && handleItemClick(item)}
                                    style={{ cursor: !item.hasSubmenu ? 'pointer' : 'default' }}
                                >
                                    <div className="menu-item-content">
                                        <div>
                                            <div className="menu-item-title">
                                                {item.title}
                                                {item.editedAt && <span className="edited-badge"> (изменено)</span>}
                                            </div>
                                            <div className="menu-item-description">{item.description}</div>
                                        </div>
                                        {canEdit && !item.hasSubmenu && (
                                            <div className="menu-item-actions">
                                                {isSuperAdmin && hoveredMenu === 'broadcasts' && (
                                                    <button
                                                        className="download-item-btn"
                                                        onClick={(e) => {
                                                            e.stopPropagation();
                                                            handleDownloadBroadcast(item);
                                                        }}
                                                        title="Скачать эфир"
                                                    >
                                                        ⬇️
                                                    </button>
                                                )}
                                                <button
                                                    className="edit-item-btn"
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        handleEditItem(hoveredMenu, item);
                                                    }}
                                                    title="Редактировать"
                                                >
                                                    ✏️
                                                </button>
                                                <button
                                                    className="delete-item-btn"
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        handleDeleteItem(hoveredMenu, item.id, item.title);
                                                    }}
                                                    title="Удалить"
                                                >
                                                    🗑️
                                                </button>
                                            </div>
                                        )}
                                        {item.hasSubmenu && <span className="submenu-arrow">▶</span>}
                                    </div>
                                </div>
                            ))
                        ) : (
                            !isAdmin && <div className="empty-dropdown">Контент пока не добавлен</div>
                        )}
                    </div>
                )}

                {hoveredSubmenu && (
                    <div
                        className="menu-submenu-positioned"
                        style={{ top: submenuPosition.top, left: submenuPosition.left }}
                        onMouseEnter={handleDropdownEnter}
                        onMouseLeave={handleDropdownLeave}
                    >
                        {isAdmin && (
                            <div className="submenu-add-section">
                                <button
                                    className="submenu-add-btn"
                                    onClick={() => handleAddContent('broadcasts', 'broadcasts-guests')}
                                >
                                    Добавить эфир с гостем
                                </button>
                            </div>
                        )}
                        {(menuData['broadcasts-guests'] || []).map((item) => (
                            <div
                                key={item.id}
                                className="menu-dropdown-item"
                                onClick={() => handleItemClick(item)}
                                style={{ cursor: 'pointer' }}
                            >
                                <div className="menu-item-content">
                                    <div>
                                        <div className="menu-item-title">
                                            {item.title}
                                            {item.editedAt && <span className="edited-badge"> (изменено)</span>}
                                        </div>
                                        <div className="menu-item-description">{item.description}</div>
                                    </div>
                                    {canEdit && (
                                        <div className="menu-item-actions">
                                            {isSuperAdmin && (
                                                <button
                                                    className="download-item-btn"
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        handleDownloadBroadcast(item);
                                                    }}
                                                    title="Скачать эфир"
                                                >
                                                    ⬇️
                                                </button>
                                            )}
                                            <button
                                                className="edit-item-btn"
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    handleEditItem('broadcasts-guests', item);
                                                }}
                                                title="Редактировать"
                                            >
                                                ✏️
                                            </button>
                                            <button
                                                className="delete-item-btn"
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    handleDeleteItem('broadcasts-guests', item.id, item.title);
                                                }}
                                                title="Удалить"
                                            >
                                                🗑️
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                        {(!menuData['broadcasts-guests'] || menuData['broadcasts-guests'].length === 0) && !isAdmin && (
                            <div className="empty-submenu">Пока нет эфиров</div>
                        )}
                    </div>
                )}
            </div>

            {/* Модальное окно подтверждения удаления */}
            {showDeleteConfirm && itemToDelete && (
                <div className="modal-overlay" onClick={cancelDeleteItem}>
                    <div className="modal-content" onClick={(e) => e.stopPropagation()}>
                        <div className="modal-header">
                            <span className="modal-icon">🗑️</span>
                            <h3>Подтверждение удаления</h3>
                        </div>
                        <div className="modal-body">
                            <p>Вы действительно хотите удалить эту запись?</p>
                            <div className="item-preview">
                                <strong>{itemToDelete.itemTitle}</strong>
                            </div>
                            <p className="warning-text">Это действие невозможно отменить!</p>
                        </div>
                        <div className="modal-footer">
                            <button className="modal-btn cancel" onClick={cancelDeleteItem}>
                                ❌ Отмена
                            </button>
                            <button className="modal-btn confirm" onClick={executeDeleteItem}>
                                ✅ Да, удалить
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Встроенная модалка добавления контента с записью аудио */}
            {showAddModal && (
                <div className="modal-overlay" onClick={() => {
                    setShowAddModal(false);
                    setSelectedMenuId(null);
                    setEditingItem(null);
                    setNewItemTitle('');
                    setNewItemDescription('');
                    setNewItemMediaUrl('');
                    setNewItemMediaType('');
                    setIsRecording(false);
                    setRecordingTime(0);
                }}>
                    <div className="modal-content" onClick={(e) => e.stopPropagation()}>
                        <h3>{editingItem ? 'Редактировать контент' : 'Добавить контент'}</h3>
                        <input
                            type="text"
                            placeholder="Как будет отображаться"
                            value={newItemTitle}
                            onChange={(e) => setNewItemTitle(e.target.value)}
                            className="modal-input"
                        />
                        <textarea
                            placeholder="Сюда вставить ссылку"
                            value={newItemDescription}
                            onChange={(e) => setNewItemDescription(e.target.value)}
                            className="modal-textarea"
                        />

                        <div className="media-controls-dashboard">
                            <div className="media-buttons-dashboard">
                                {/* Для раздела Эфиры показываем только Аудио и Видео */}
                                {selectedMenuId === 'broadcasts' || selectedMenuId === 'broadcasts-guests' ? (
                                    <>
                                        <label className="attach-button-dashboard">
                                            Видео
                                            <input
                                                type="file"
                                                accept="video/*"
                                                onChange={(e) => handleFileUpload(e, 'video')}
                                                style={{ display: 'none' }}
                                            />
                                        </label>
                                        <label className="attach-button-dashboard">
                                            Аудио
                                            <input
                                                type="file"
                                                accept="audio/*"
                                                onChange={(e) => handleFileUpload(e, 'audio')}
                                                style={{ display: 'none' }}
                                            />
                                        </label>
                                        <button
                                            className={`mic-button-dashboard ${isRecording ? 'recording' : ''}`}
                                            onClick={isRecording ? stopRecording : startRecording}
                                        >
                                            {isRecording ? '⏹️ Остановить' : '🎤 Записать голос'}
                                        </button>
                                    </>
                                ) : selectedMenuId === 'music' ? (
                                    /* Для раздела Музыка только Аудио */
                                    <>
                                        <label className="attach-button-dashboard">
                                            Аудио
                                            <input
                                                type="file"
                                                accept="audio/*"
                                                onChange={(e) => handleFileUpload(e, 'audio')}
                                                style={{ display: 'none' }}
                                            />
                                        </label>
                                        <button
                                            className={`mic-button-dashboard ${isRecording ? 'recording' : ''}`}
                                            onClick={isRecording ? stopRecording : startRecording}
                                        >
                                            {isRecording ? '⏹️ Остановить' : '🎤 Записать голос'}
                                        </button>
                                    </>
                                ) : selectedMenuId === 'movies' ? (
                                    /* Для раздела Фильмы только Видео */
                                    <label className="attach-button-dashboard">
                                        Видео
                                        <input
                                            type="file"
                                            accept="video/*"
                                            onChange={(e) => handleFileUpload(e, 'video')}
                                            style={{ display: 'none' }}
                                        />
                                    </label>
                                ) : (
                                    <>
                                        <label className="attach-button-dashboard">
                                            Фото
                                            <input
                                                type="file"
                                                accept="image/*"
                                                onChange={(e) => handleFileUpload(e, 'image')}
                                                style={{ display: 'none' }}
                                            />
                                        </label>
                                        <label className="attach-button-dashboard">
                                            Видео
                                            <input
                                                type="file"
                                                accept="video/*"
                                                onChange={(e) => handleFileUpload(e, 'video')}
                                                style={{ display: 'none' }}
                                            />
                                        </label>
                                        <label className="attach-button-dashboard">
                                            Аудио
                                            <input
                                                type="file"
                                                accept="audio/*"
                                                onChange={(e) => handleFileUpload(e, 'audio')}
                                                style={{ display: 'none' }}
                                            />
                                        </label>
                                        <button
                                            className={`mic-button-dashboard ${isRecording ? 'recording' : ''}`}
                                            onClick={isRecording ? stopRecording : startRecording}
                                        >
                                            {isRecording ? '⏹️ Остановить' : '🎤 Записать голос'}
                                        </button>
                                    </>
                                )}
                            </div>

                            {isRecording && (
                                <div className="recording-indicator-dashboard">
                                    <span className="recording-dot">🔴</span>
                                    <span className="recording-time">{formatRecordingTime(recordingTime)}</span>
                                </div>
                            )}

                            {newItemMediaUrl && (
                                <div className="attached-file-dashboard">
                                    <span className="file-info">
                                        {newItemMediaType === 'image' && '📷 Фото прикреплено'}
                                        {newItemMediaType === 'video' && '🎬 Видео прикреплено'}
                                        {newItemMediaType === 'audio' && '🎵 Аудио прикреплено'}
                                    </span>
                                    <button
                                        className="remove-file-dashboard"
                                        onClick={() => {
                                            setNewItemMediaUrl('');
                                            setNewItemMediaType('');
                                        }}
                                    >
                                        ✕
                                    </button>
                                </div>
                            )}
                        </div>

                        <div className="modal-buttons">
                            <button className="modal-btn save" onClick={handleSaveContent}>
                                Сохранить
                            </button>
                            <button className="modal-btn cancel" onClick={() => {
                                setShowAddModal(false);
                                setSelectedMenuId(null);
                                setNewItemTitle('');
                                setNewItemDescription('');
                                setNewItemMediaUrl('');
                                setNewItemMediaType('');
                                setIsRecording(false);
                                setRecordingTime(0);
                            }}>
                                Отмена
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Dashboard;
